<script setup lang="ts">import { useQuery } from '@tanstack/vue-query';import { adminApi } from '../api';import DsBadge from '@/shared/ui/DsBadge.vue';import DsCard from '@/shared/ui/DsCard.vue';import DsPageHeader from '@/shared/ui/DsPageHeader.vue';import DsState from '@/shared/ui/DsState.vue';const q=useQuery({queryKey:['admin','roles'],queryFn:adminApi.roles})</script><template><section><DsPageHeader eyebrow="ACCESS CONTROL" title="Role Management" description="Define reusable permission sets for application users."/><DsState v-if="q.isPending.value" kind="loading"/><DsState v-else-if="q.isError.value" kind="error" title="Unable to load roles"/><div v-else class="grid"><DsCard v-for="r in q.data.value" :key="r.Code"><div class="row"><h3>{{r.Name}}</h3><DsBadge v-if="r.IsSystem">System</DsBadge></div><code>{{r.Code}}</code><p>{{r.Description||'No description provided.'}}</p><small>{{r.Permissions?.length??0}} permissions</small></DsCard></div></section></template><style scoped>section{padding:32px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center}h3{margin:0}code,small,p{color:var(--ds-text-secondary)}@media(max-width:640px){section{padding:20px}}</style>